const source = $('Capture lead details').item.json;
const firstName = String(source.firstName ?? '').trim();
const lastName = String(source.lastName ?? '').trim();
const workEmail = String(source.workEmail ?? '').trim().toLowerCase();
const companyName = String(source.companyName ?? '').trim();
const jobTitle = String(source.jobTitle ?? '').trim();
const rawWebsite = String(source.companyWebsite ?? '').trim();
const website = /^https?:\/\//i.test(rawWebsite) ? rawWebsite.replace(/\/$/, '') : 'https://' + rawWebsite.replace(/\/$/, '');
const domain = website.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
const teamSize = Math.max(0, Number(source.teamSize) || 0);
const estimatedBudget = Math.max(0, Number(source.estimatedBudget) || 0);
const urgency = String(source.urgency ?? 'Just exploring');
let leadScore = estimatedBudget >= 25000 ? 40 : estimatedBudget >= 10000 ? 25 : estimatedBudget >= 5000 ? 15 : 5;
leadScore += teamSize >= 100 ? 30 : teamSize >= 25 ? 20 : teamSize >= 5 ? 10 : 5;
leadScore += urgency === 'Within 30 days' ? 30 : urgency === '1–3 months' ? 20 : 5;
const closeInDays = urgency === 'Within 30 days' ? 30 : urgency === '1–3 months' ? 90 : 180;
return { json: { firstName, lastName, workEmail, jobTitle, companyName, website, domain, teamSize, estimatedBudget, urgency, projectSummary: String(source.projectSummary ?? '').trim(), leadScore, qualified: leadScore >= 60, closeInDays, submittedAt: source.submittedAt ?? new Date().toISOString() } };
